package com.ultras.bans.discord;
import com.ultras.bans.ULTRASBansPlugin; import com.ultras.bans.model.PunishmentRecord; import java.net.URI; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.util.concurrent.*;
public final class DiscordService {private final ULTRASBansPlugin plugin;private final ExecutorService exec=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"ULTRAS-BANS-DISCORD");t.setDaemon(true);return t;});private long last;
 public DiscordService(ULTRASBansPlugin p){plugin=p;}
 public void punishment(PunishmentRecord r){var c=plugin.configs().discord("config");if(!c.getBoolean("enabled",false))return;String url=c.getString("webhook-url","");if(url.isBlank())return;long wait=c.getLong("rate-limit-ms",750);long now=System.currentTimeMillis();long delay=Math.max(0,wait-(now-last));last=now+delay;exec.submit(()->{try{if(delay>0)Thread.sleep(delay);String title="ULTRAS BANS • "+r.type();String desc="**Player:** "+esc(r.username())+"\n**UUID:** `"+r.uuid()+"`\n**Punishment:** `"+r.type()+"`\n**Duration:** `"+(r.permanent()?"Permanent":com.ultras.bans.utility.DurationUtil.format(r.durationSeconds()))+"`\n**Reason:** "+esc(r.reason())+"\n**Operator:** "+esc(r.operator())+"\n**Server:** "+esc(r.server())+"\n**Time:** "+r.createdAt();String json="{\"username\":\"ULTRAS BANS\",\"embeds\":[{\"title\":\""+json(title)+"\",\"description\":\""+json(desc)+"\"}]}";HttpRequest req=HttpRequest.newBuilder(URI.create(url)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json,StandardCharsets.UTF_8)).build();HttpClient.newHttpClient().sendAsync(req,HttpResponse.BodyHandlers.discarding());}catch(Exception e){plugin.getLogger().warning("Discord webhook failed: "+e.getMessage());}});}
 private String esc(String s){return s==null?"":s.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ");}private String json(String s){return esc(s);}public void shutdown(){exec.shutdown();}}
